command:
/**
 * TRANSFER CONTROL OF A PRESENTATION
 *
 * Run this macro while a synchronized presentation is active.
 * Set CONTROLLER to the exact name or ID of the new controller.
 * The new controller must be connected.
 */

// ── CONFIGURATION TO EDIT ─────────────────────────────────────
const CONTROLLER = "REPLACE_ME"; // Example: "Alice"
// ──────────────────────────────────────────────────────────────

if (!game.user.isGM) return ui.notifications.error("This macro is for the GM only.");
const api = game.modules.get("retro-crt-terminal")?.api;
if (!api) return ui.notifications.error("Retro CRT Terminal is not active.");
if (!api.shared.state?.active) return ui.notifications.warn("No synchronized presentation is active.");
if (!CONTROLLER || CONTROLLER === "REPLACE_ME") {
  return ui.notifications.warn("Edit CONTROLLER in the macro configuration.");
}

const controller = game.users.get(CONTROLLER) ?? game.users.find(user => user.name === CONTROLLER);
if (!controller) return ui.notifications.error(`User not found: ${CONTROLLER}`);
if (!controller.active) return ui.notifications.error(`${controller.name} is not connected.`);

await api.shared.update({ controllerUserId: controller.id });
ui.notifications.info(`Control transferred to ${controller.name}.`);
